void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 xy = fragCoord.xy; 
    vec3 frac = vec3(0, 0, 0);

    if (xy.x >= (iResolution.x / 2.0 - (iResolution.y) / 2.0) && xy.x <= (iResolution.x / 2.0 + (iResolution.y) / 2.0)) {
        frac = vec3(1, 1, 1);
    }

    float val = 1.0;

    float x_border = (iResolution.x / 2.0 - (iResolution.y) / 2.0);

    float xCur = iResolution.y;
    float yCur = iResolution.y;
    float x_border_cur = x_border;
    float y_border_cur = 0.0;

    for(float i = 0.0; i < 5.0; i += 1.0) {
        xCur = xCur / 3.0;
        yCur = yCur / 3.0;
        x_border_cur = xCur * 3.0;
        y_border_cur = yCur * 3.0;

       for (float j = 0.0; j < pow(3.0, i); j += 1.0) {
           for (float g = 0.0; g < pow(3.0, i); g += 1.0) {
               if ((xy.x >= x_border + x_border_cur * g + xCur && xy.x <= x_border + x_border_cur * g + xCur * 2.0) && (xy.y >= yCur + y_border_cur * j && xy.y <= yCur * 2.0 + y_border_cur * j)) {
                   frac = vec3(0, 0, 0);
               }   
           }
       }
    }

    fragColor = vec4(frac,1.0);
}
